package review

import "testing"

func TestSectionRoundTrip(t *testing.T) {
	patch := "@@ -1 +1 @@\n-old\n+new"
	source := BuildDiff("a.go", patch)
	if got := Section(source, "a.go"); got != patch { t.Fatalf("section = %q", got) }
	if got := Section(source, "missing.go"); got != "" { t.Fatalf("unexpected section %q", got) }
}

