package review

import "strings"

func BuildDiff(path, patch string) string {
	return "### " + path + "\n" + patch
}

func Section(source, path string) string {
	header := "### " + path + "\n"
	start := strings.Index(source, header)
	if start < 0 { return "" }
	content := source[start+len(header):]
	if end := strings.Index(content, "\n### "); end >= 0 { return content[:end] }
	return content
}
